const obs = $input.all()[0].json.observations;
const latest = parseFloat(obs[obs.length - 1].value);
const inverted = latest < 0;
const health = inverted ? 35.0 : 78.5;
return [{ json: { macro_health_score: health, recession_probability: inverted ? 0.68 : 0.12, liquidity_regime: inverted ? 'DEFENSIVE' : 'EXPANSIONARY', yield_curve_inverted: inverted, timestamp: new Date().toISOString() } }];
